input.new_str:
                            const coords = positionToCoordinate(x, y);

                            // 更新任务坐标
                            const taskIndex = tasks.findIndex(t => t.id === dragTask.id);
                            if (taskIndex !== -1) {
                                tasks[taskIndex].urgency = coords.urgency;
                                tasks[taskIndex].importance = coords.importance;
                                tasks[taskIndex].updatedAt = new Date().toISOString();
                                localStorage.setItem('tasks', JSON.stringify(tasks));
                            }

                            renderTasks();
                            dragTask = null;

                            document.removeEventListener('mousemove', moveHandler);
                            document.removeEventListener('mouseup', upHandler);
                        };

                        document.addEventListener('mousemove', moveHandler);
                        document.addEventListener('mouseup', upHandler);
                    }
                });

                matrix.appendChild(taskElement);
            });
        }

        function showContextMenu(e, taskId) {
            currentTaskId = taskId;
            const menu = document.getElementById('contextMenu');
            menu.style.left = e.pageX + 'px';
            menu.style.top = e.pageY + 'px';
            menu.style.display = 'block';
        }

        function editTask() {
            document.getElementById('contextMenu').style.display = 'none';
            showEditTaskModal(currentTaskId);
        }

        function completeTask() {
            const taskIndex = tasks.findIndex(t => t.id === currentTaskId);
            if (taskIndex !== -1) {
                tasks[taskIndex].completed = true;
                tasks[taskIndex].completedAt = new Date().toISOString();
                localStorage.setItem('tasks', JSON.stringify(tasks));
                renderTasks();
                updateUserProfile();
            }
            document.getElementById('contextMenu').style.display = 'none';
        }

        function deleteTask() {
            if (confirm('确定要删除这个任务吗？')) {
                tasks = tasks.filter(t => t.id !== currentTaskId);
                localStorage.setItem('tasks', JSON.stringify(tasks));
                renderTasks();
                updateUserProfile();
            }
            document.getElementById('contextMenu').style.display = 'none';
        }

        function updateImportanceDisplay(value) {
            document.getElementById('currentImportance').textContent = value + '星';
        }

        function updateUrgencyDisplay(value) {
            document.getElementById('currentUrgency').textContent = urgencyLabels[value];
        }

        function showUserProfile() {
            document.getElementById('main-page').style.display = 'none';
            document.getElementById('user-page').style.display = 'block';
            updateUserProfile();
        }

        function showMainPage() {
            document.getElementById('main-page').style.display = 'block';
            document.getElementById('user-page').style.display = 'none';
        }

        function updateUserProfile() {
            updateCreatedTasks();
            updateCompletedTasks();
        }

        function updateCreatedTasks() {
            const container = document.getElementById('created-tasks');
            const createdTasks = tasks.slice().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

            if (createdTasks.length === 0) {
                container.innerHTML = '<p style="color: #999; text-align: center; padding: 20px;">暂无创建的任务</p>';
                return;
            }

            container.innerHTML = createdTasks.map(task => `
                <div class="timeline-item">
                    <div class="timeline-date">${formatDate(task.createdAt)}</div>
                    <div class="timeline-content">
                        <div class="timeline-title">${task.title}</div>
                        <div class="timeline-desc">
                            ${task.description || '无描述'} | 
                            重要程度: ${task.importance}星 | 
                            紧急程度: ${urgencyLabels[task.urgency]} |
                            分类: ${getCategoryName(task.category)}
                            ${task.completed ? ' | ✅ 已完成' : ''}
                        </div>
                    </div>
                </div>
            `).join('');
        }

        function updateCompletedTasks() {
            const container = document.getElementById('completed-tasks');
            const completedTasks = tasks.filter(t => t.completed).sort((a, b) => new Date(b.completedAt) - new Date(a.completedAt));

            if (completedTasks.length === 0) {
                container.innerHTML = '<p style="color: #999; text-align: center; padding: 20px;">暂无完成的任务</p>';
                return;
            }

            container.innerHTML = completedTasks.map(task => `
                <div class="timeline-item">
                    <div class="timeline-date">${formatDate(task.completedAt)}</div>
                    <div class="timeline-content">
                        <div class="timeline-title">✅ ${task.title}</div>
                        <div class="timeline-desc">
                            ${task.description || '无描述'} | 
                            重要程度: ${task.importance}星 | 
                            紧急程度: ${urgencyLabels[task.urgency]} |
                            分类: ${getCategoryName(task.category)}
                        </div>
                    </div>
                </div>
            `).join('');
        }

        function formatDate(dateString) {
            const date = new Date(dateString);
            const now = new Date();
            const diffTime = Math.abs(now - date);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays === 1) {
                return '今天 ' + date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
            } else if (diffDays === 2) {
                return '昨天 ' + date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
            } else if (diffDays <= 7) {
                return diffDays + '天前';
            } else {
                return date.toLocaleDateString('zh-CN') + ' ' + date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
            }
        }

        function getCategoryName(category) {
            const categoryMap = {
                'work': '工作',
                'personal': '个人',
                'study': '学习',
                'health': '健康',
                'family': '家庭',
                'other': '其他'
            };
            return categoryMap[category] || '其他';
        }

        // 初始化示例数据（仅在第一次访问时）
        function initSampleData() {
            if (tasks.length === 0) {
                const sampleTasks = [
                    {
                        id: '1',
                        title: '完成项目报告',
                        description: '准备季度总结报告，包括数据分析和建议',
                        category: 'work',
                        importance: 6,
                        urgency: 7,
                        createdAt: new Date(Date.now() - 2 * 24 * 60 * 60 * 1000).toISOString(),
                        completed: false
                    },
                    {
                        id: '2',
                        title: '健身锻炼',
                        description: '每周至少3次有氧运动',
                        category: 'health',
                        importance: 5,
                        urgency: 3,
                        createdAt: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(),
                        completed: false
                    },
                    {
                        id: '3',
                        title: '学习新技能',
                        description: '学习React和Vue框架',
                        category: 'study',
                        importance: 4,
                        urgency: 1,
                        createdAt: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
                        completed: true,
                        completedAt: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString()
                    }
                ];

                tasks = sampleTasks;
                localStorage.setItem('tasks', JSON.stringify(tasks));
            }
        }

        // 页面加载完成后初始化示例数据
        document.addEventListener('DOMContentLoaded', function() {
            initSampleData();
            renderTasks();
        });

        // 键盘快捷键
        document.addEventListener('keydown', function(e) {
            // ESC键关闭模态框
            if (e.key === 'Escape') {
                closeTaskModal();
                document.getElementById('contextMenu').style.display = 'none';
            }

            // Ctrl+N 新建任务
            if (e.ctrlKey && e.key === 'n') {
                e.preventDefault();
                // 在中心位置显示添加按钮
                const addButton = document.getElementById('addButton');
                addButton.dataset.x = '400';
                addButton.dataset.y = '300';
                showAddTaskModal();
            }
        });

        // 窗口大小改变时重新渲染
        window.addEventListener('resize', function() {
            setTimeout(renderTasks, 100);
        });

        // 导出/导入功能
        function exportTasks() {
            const dataStr = JSON.stringify(tasks, null, 2);
            const dataBlob = new Blob([dataStr], {type: 'application/json'});
            const url = URL.createObjectURL(dataBlob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'tasks-backup-' + new Date().toISOString().split('T')[0] + '.json';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
        }

        function importTasks(event) {
            const file = event.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = function(e) {
                try {
                    const importedTasks = JSON.parse(e.target.result);
                    if (Array.isArray(importedTasks)) {
                        if (confirm('确定要导入任务吗？这将替换当前所有任务。')) {
                            tasks = importedTasks;
                            localStorage.setItem('tasks', JSON.stringify(tasks));
                            renderTasks();
                            updateUserProfile();
                            alert('任务导入成功！');
                        }
                    } else {
                        alert('文件格式不正确');
                    }
                } catch (error) {
                    alert('文件解析失败：' + error.message);
                }
            };
            reader.readAsText(file);
        }

        // 统计功能
        function getTaskStats() {
            const total = tasks.length;
            const completed = tasks.filter(t => t.completed).length;
            const pending = total - completed;
            const categories = {};

            tasks.forEach(task => {
                categories[task.category] = (categories[task.category] || 0) + 1;
            });

            return {
                total,
                completed,
                pending,
                completionRate: total > 0 ? Math.round((completed / total) * 100) : 0,
                categories
            };
        }

        // 添加统计显示到用户资料页面
        function addStatsToProfile() {
            const stats = getTaskStats();
            const profileHeader = document.querySelector('.profile-header');

            const statsHTML = `
                <div style="display: flex; justify-content: center; gap: 30px; margin-top: 20px; flex-wrap: wrap;">
                    <div style="text-align: center;">
                        <div style="font-size: 24px; font-weight: bold;">${stats.total}</div>
                        <div style="font-size: 14px; opacity: 0.8;">总任务</div>
                    </div>
                    <div style="text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; color: #4CAF50;">${stats.completed}</div>
                        <div style="font-size: 14px; opacity: 0.8;">已完成</div>
                    </div>
                    <div style="text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; color: #ff9800;">${stats.pending}</div>
                        <div style="font-size: 14px; opacity: 0.8;">进行中</div>
                    </div>
                    <div style="text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; color: #2196F3;">${stats.completionRate}%</div>
                        <div style="font-size: 14px; opacity: 0.8;">完成率</div>
                    </div>
                </div>
            `;

            if (!profileHeader.querySelector('.stats-container')) {
                const statsContainer = document.createElement('div');
                statsContainer.className = 'stats-container';
                statsContainer.innerHTML = statsHTML;
                profileHeader.appendChild(statsContainer);
            }
        }

        // 更新用户资料时也更新统计
        const originalUpdateUserProfile = updateUserProfile;
        updateUserProfile = function() {
            originalUpdateUserProfile();
            addStatsToProfile();
        };
    </script>
</body>
</html>
